import sys

def is_acyclic(graph):
    visited = [False] * len(graph)
    rec_stack = [False] * len(graph)

    def dfs(v):
        visited[v] = True
        rec_stack[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[v] = False
        return False

    for node in range(len(graph)):
        if not visited[node]:
            if dfs(node):
                return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    graph = [[] for _ in range(n)]
    edges = []
    for _ in range(m):
        u = int(input[index]) - 1
        v = int(input[index + 1]) - 1
        index += 2
        graph[u].append(v)
        edges.append((u, v))

    for u, v in edges:
        graph[u].remove(v)
        if is_acyclic(graph):
            print("YES")
            return
        graph[u].append(v)

    print("NO")

main()
